const fs = require('fs');
const assert = require('assert');

// 1. Verify JSON file syntax and required fields
const rawJson = fs.readFileSync('wikimedia-commons-video.json', 'utf8');
const rule = JSON.parse(rawJson);

assert.strictEqual(rule.version, 2, 'Version must be 2');
assert.strictEqual(rule.title, '维基共享资源视频 (Wikimedia Commons)');
assert.ok(rule.url.includes('page=fypage'), 'URL should have page=fypage');
assert.ok(!rule.url.includes('gsroffset=fypage'), 'URL must NOT have gsroffset=fypage');
assert.ok(rule.find_rule.includes('(page - 1) * 20'), 'find_rule must calculate offset from page');
assert.ok(rule.search_rule.includes('(page - 1) * 20'), 'search_rule must calculate offset from page');

// 2. Verify TXT base64 file matches JSON
const txt = fs.readFileSync('wikimedia-commons-video.txt', 'utf8');
const match = txt.match(/base64:\/\/@.*?@(.*?)$/);
assert.ok(match, 'TXT file must contain base64 share payload');
const decodedFromTxt = JSON.parse(Buffer.from(match[1], 'base64').toString('utf8'));
assert.strictEqual(decodedFromTxt.version, 2, 'Share code version must match');
assert.strictEqual(decodedFromTxt.url, rule.url, 'Share code url must match');

// 3. Verify offset calculations
for (let p = 1; p <= 5; p++) {
  const offset = (p - 1) * 20;
  assert.strictEqual(offset, (p - 1) * 20);
}

console.log('ALL LOCAL CHECKS PASSED: wikimedia-commons-video v2 is intact and verified.');
